using Microsoft.Windows.AppNotifications.Builder;using SobhanNotificationHub.Models;
namespace SobhanNotificationHub.Notifications;public static class NotificationRenderer{public static AppNotificationBuilder Build(SobhanNotification n,ClientConfig config){var module=config.Modules.GetValueOrDefault(n.Module,new());var sensitive=n.Module is "hr" or "management";var localBody=App.Services.Settings.LocalShowBody;var body=(!sensitive&&localBody&&module.ShowBody)?n.Body:n.SafeBody;var builder=new AppNotificationBuilder().AddArgument("notificationId",n.Id.ToString()).AddArgument("action","open").AddText(Limit(n.Title,190)).AddText(Limit(body,240)).SetTag($"sobhan-{n.Id}").SetGroup(n.Module);if(!App.Services.Settings.LocalSoundEnabled||!config.Client.EnableSound||module.Sound=="silent")builder.MuteAudio();if(config.Client.EnableActionButtons){var actions=n.Actions.Take(3).ToList();var reply=actions.Any(a=>a.Id=="reply")&&module.AllowQuickReply&&config.Client.EnableQuickReply;if(reply)builder.AddTextBox("replyText","پاسخ خود را بنویسید","پاسخ سریع");foreach(var a in actions){var button=new AppNotificationButton(Limit(a.Label,40)).AddArgument("notificationId",n.Id.ToString()).AddArgument("action",a.Id);builder.AddButton(button);}}return builder;}private static string Limit(string? value,int max){value=string.IsNullOrWhiteSpace(value)?"اعلان جدید سبحان":value.Trim();return value.Length>max?value[..max]+"…":value;}}
